import pytest

from src.admin import Forbidden
from src.admin.reports import revenue_by_tenant


class User:
    def __init__(self, is_admin):
        self.is_admin = is_admin


class FakeDb:
    def query(self, sql, params):
        return [("t1", 10)]


def test_non_admin_is_refused():
    with pytest.raises(Forbidden):
        revenue_by_tenant(FakeDb(), User(False))


def test_admin_sees_all_tenants():
    assert revenue_by_tenant(FakeDb(), User(True)) == [("t1", 10)]
